/* Event structure */

typedef struct velawear_event
{
  uint32_t type;
  uint32_t priority;
  uint32_t timestamp;
  union
    {
      struct
        {
          float x;
          float y;
          float z;
        } imu;
      struct
        {
          int motion_type;
          float intensity;
        } motion;
      struct
        {
          char text[256];
          int length;
        } audio;
      struct
        {
          char data[512];
          int length;
        } ble;
      struct
        {
          int x;
          int y;
          int gesture;
        } touch;
      struct
        {
          int id;
        } timer;
    } data;
} velawear_event_t;

/* State structure */

typedef struct velawear_state
{
  /* Device state */

  uint32_t battery_level;
  bool is_charging;
  int power_mode;
  uint32_t free_memory;
  uint32_t uptime_seconds;

  /* User state */

  bool is_moving;
  bool is_running;
  bool is_sleeping;
  float heart_rate;
  float temperature;

  /* Environment state */

  bool ble_connected;
  char ble_device_name[64];
  bool has_network;
  int signal_strength;

  /* History */

  uint32_t last_move_time;
  uint32_t last_interaction_time;
  uint32_t fall_count_today;
  uint32_t move_count_today;
} velawear_state_t;

/* Action structure */

typedef struct velawear_action
{
  int type;
  uint32_t priority;
  union
    {
      struct
        {
          char text[256];
        } display;
      struct
        {
          int duration_ms;
          int pattern;
        } vibrate;
      struct
        {
          char data[512];
          int length;
        } ble;
      struct
        {
          char prompt[1024];
        } llm;
    } params;
} velawear_action_t;

/* Configuration structure */

typedef struct velawear_config
{
  int imu_sample_rate_hz;
  int sedentary_threshold_sec;
  float fall_accel_threshold_g;
  int event_queue_size;
  bool llm_enabled;
  bool ble_enabled;
} velawear_config_t;

/* LLM client structure */

typedef struct velawear_llm
{
  bool initialized;
  bool connected;
  char model_name[64];
  int request_count;
} velawear_llm_t;

/* Audio sensor structure */

typedef struct velawear_audio
