    // rt_kputs(data);

    topic_buf_pool = &ctx->topic_buf_pool;
    buf = &topic_buf_pool->buf[topic_buf_pool->rd_idx];
    RT_ASSERT(buf->buf);

    RT_ASSERT(buf->used_len + len <= buf->total_len);
    memcpy(buf->buf + buf->used_len, data, len);
    buf->used_len += len;
    if (!flags)
    {
        /* wait for last fragment */
        return;
    }

