    cJSON_AddStringToObject(params, "role", "node");
    cJSON_AddItemToObject(params, "scopes", cJSON_CreateArray());

    if (s_gateway_token[0]) {
        cJSON* auth = cJSON_CreateObject();
        cJSON_AddStringToObject(auth, "token", s_gateway_token);
