typedef enum {
    BT_ADAPTER_STATE_OFF = 0,
    BT_ADAPTER_STATE_BLE_TURNING_ON,
    BT_ADAPTER_STATE_BLE_ON,
    BT_ADAPTER_STATE_TURNING_ON,
    BT_ADAPTER_STATE_ON,
    BT_ADAPTER_STATE_TURNING_OFF,
    BT_ADAPTER_STATE_BLE_TURNING_OFF,
} bt_adapter_state_t;
/**
 * @endcond
