  while (agent->running)
    {
      uint32_t age = velawear_now_ms() - agent->watchdog_last_main_ms;

      if (age > 5000 && !reported_stall)
        {
          syslog(LOG_ERR,
                 "[Watchdog] Main loop heartbeat stalled (%lu ms)\n",
                 (unsigned long)age);
          reported_stall = true;
        }
      else if (age <= 5000)
        {
          reported_stall = false;
        }

      usleep(1000000);
    }

  syslog(LOG_INFO, "[Watchdog] Software monitor stopped\n");
  return NULL;
}

