{
  int ret;

  ret = audio_sensor_init(&agent->audio);
  if (ret < 0)
    {
      usleep(20000);
      ret = audio_sensor_init(&agent->audio);
    }

  agent->audio_available = ret == VELAWEAR_OK;
  return ret;
}

