/*
 * VelaWear XiaoZhi audio path.
 *
 * The upstream SF32 application uses SiFli audio_server callbacks and
 * RT-Thread ring buffers.  The current openvela image has the AUDCODEC HAL
 * path already exercised by audio_hw_test.c, so this adapter uses bounded
 * 60 ms PCM blocks and the same board-native DMA stream helpers.
 */

#include "xiaozhi_internal.h"
#include "xiaozhi_audio.h"

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <opus.h>

#include "../drivers/audio_hw_test.h"

#define XZ_AUDIO_TAG "XiaoZhiAudio"
#define XZ_AUDIO_RATE 16000
#define XZ_AUDIO_FRAME_MS 60
#define XZ_AUDIO_MAX_SAMPLES 2048
#define XZ_AUDIO_MAX_PACKET 4096

static unsigned int xz_audio_frame_samples(const struct xiaozhi_client *client)
{
  unsigned int rate = client->sample_rate == 0 ? XZ_AUDIO_RATE :
                                                 client->sample_rate;
  unsigned int duration = client->frame_duration_ms == 0 ? XZ_AUDIO_FRAME_MS :
                                                            client->frame_duration_ms;
  unsigned int samples = (rate * duration + 999) / 1000;

  if (samples == 0 || samples > XZ_AUDIO_MAX_SAMPLES)
    {
      return XZ_AUDIO_RATE * XZ_AUDIO_FRAME_MS / 1000;
    }
  return samples;
}

/*
 * VelaWear - SF32LB52 on-chip audio hardware test
 */

#ifndef VELAWEAR_AUDIO_HW_TEST_H
#define VELAWEAR_AUDIO_HW_TEST_H

#include <stddef.h>
#include <stdint.h>

int velawear_audio_hw_test(void);
int velawear_speaker_alert(int duration_ms, int pattern);
int velawear_music_hw_test(void);
int velawear_audio_voice_start(uint16_t stream_id,
                               uint32_t sample_count,
                               uint32_t total_bytes,
                               uint32_t crc32);
int velawear_audio_voice_write(uint16_t stream_id,
                               uint32_t offset,
                               const uint8_t *data,
                               uint16_t length);
int velawear_audio_voice_end(uint16_t stream_id,
                             uint32_t total_bytes,
                             uint32_t crc32,
                             uint32_t *sample_count);
int velawear_audio_voice_abort(uint16_t stream_id);
int velawear_audio_voice_play(uint16_t stream_id,
                              uint32_t sample_count);

/* Raw 16-bit PCM hooks for the XiaoZhi Opus adapter. */
int velawear_mic_stream_read_pcm(int16_t *samples, size_t sample_count);
int velawear_audio_pcm_play(const int16_t *samples, size_t sample_count);

#endif /* VELAWEAR_AUDIO_HW_TEST_H */

