   327	/**
   328	 * Reads requests from the quickapp process via POSIX mqueue and feeds
   329	 * them into the local message_bus inbound queue.
   330	 */
   331	static void *quickapp_mq_listener_task(void *arg)
   332	{
   333	    (void)arg;
   334	    syslog(LOG_INFO, "[%s] Quickapp mqueue listener started\n", TAG);
   335	
   336	#if !VELACLAW_MQ_SUPPORTED
   337	    syslog(LOG_WARNING,
   338	           "[%s] Quickapp mqueue disabled: board message-size limit is "
   339	           "smaller than the bridge buffer\n", TAG);
   340	    return NULL;
   341	#endif
   342	
   343	    struct mq_attr attr = {
   344	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
   345	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
   346	    };
   347	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_IN, O_RDONLY | O_CREAT, 0666, &attr);
   348	    if (mq == (mqd_t)-1) {
   349	        syslog(LOG_ERR, "[%s] Failed to open quickapp inbound mqueue: %d\n", TAG, errno);
   350	        return NULL;
   351	    }
   352	
   353	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
   354	    if (!buf) {
   355	        syslog(LOG_ERR, "[%s] Failed to allocate mqueue recv buffer\n", TAG);
   356	        mq_close(mq);
   357	        return NULL;
   358	    }
   359	
   360	    while (1) {
   361	        ssize_t n = mq_receive(mq, buf, VELACLAW_MQ_MSG_SIZE, NULL);
   362	        if (n < 0) {
   363	            if (errno == EINTR) continue;
   364	            syslog(LOG_ERR, "[%s] mq_receive failed: %d\n", TAG, errno);
   365	            break;
   366	        }
   367	        if (n >= (ssize_t)VELACLAW_MQ_MSG_SIZE) {
   368	            n = VELACLAW_MQ_MSG_SIZE - 1;
   369	        }
   370	        buf[n] = '\0';
   371	
   372	        /* Message format: "chat_id\nquery" */
   373	        char *sep = strchr(buf, '\n');
   374	        if (!sep) {
   375	            syslog(LOG_WARNING, "[%s] Malformed quickapp message\n", TAG);
   376	            continue;
   377	        }
   378	        *sep = '\0';
   379	        const char *chat_id = buf;
   380	        const char *query = sep + 1;
   381	
   382	        syslog(LOG_INFO, "[%s] Quickapp request: chat_id=%s query=%.40s\n",
   383	               TAG, chat_id, query);
   384	
   385	        agent_msg_t msg = {0};
   386	        strncpy(msg.channel, AGENT_CHAN_QUICKAPP, sizeof(msg.channel) - 1);
   387	        strncpy(msg.chat_id, chat_id, sizeof(msg.chat_id) - 1);
   388	        msg.content = strdup(query);
   389	        if (msg.content) {
   390	            message_bus_push_inbound(&msg);
   391	        }
   392	    }
